import 'dart:async';

class Debouncer {
  Debouncer(this.delay);
  final Duration delay;
  Timer? _timer;

  void run(void Function() action) {
    _timer?.cancel();               // the previous call simply never happens
    _timer = Timer(delay, action);
  }

  void dispose() => _timer?.cancel();   // without this the callback outlives the screen
}

class Throttler {
  Throttler(this.window);
  final Duration window;
  DateTime? _lastRun;

  // Leading edge: the first call of a burst wins, the rest are dropped.
  void run(void Function() action) {
    final now = DateTime.now();
    if (_lastRun == null || now.difference(_lastRun!) >= window) {
      _lastRun = now;
      action();
    }
  }
}

class _SearchState extends State<SearchField> {
  final _debounce = Debouncer(const Duration(milliseconds: 300));

  void _onChanged(String query) => _debounce.run(() => widget.onSearch(query));

  @override
  void dispose() {
    _debounce.dispose();            // ✅ cancels a pending fire
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => TextField(onChanged: _onChanged);
}

