typedef Section = ({DateTime day, List<Txn> items});

DateTime _dayOf(DateTime t) {
  final local = t.toLocal();                    // the server sends UTC
  return DateTime(local.year, local.month, local.day);   // time stripped
}

List<Section> sections(List<Txn> txns) {
  final byDay = txns.fold(<DateTime, List<Txn>>{}, (acc, t) {
    acc.putIfAbsent(_dayOf(t.at), () => <Txn>[]).add(t);
    return acc;
  });

  final days = byDay.keys.toList()..sort((a, b) => b.compareTo(a));   // newest first
  return [for (final d in days) (day: d, items: byDay[d]!)];
}

void variants(List<Txn> txns) {
  final same = groupBy(txns, (Txn t) => _dayOf(t.at));   // ✅ same result, one line

  // ❌ Full precision key: one "section" per transaction
  final broken = groupBy(txns, (Txn t) => t.at);

  // ❌ Grouped by the UTC calendar day: a 01:30 local purchase lands under yesterday
  final wrong = groupBy(txns, (Txn t) => DateTime.utc(t.at.year, t.at.month, t.at.day));
}

