sealed class Result<T, E> {
  const Result();

  R fold<R>(R Function(T value) onOk, R Function(E error) onErr) => switch (this) {
        Ok(:final value) => onOk(value),
        Err(:final error) => onErr(error),
      };

  Result<R, E> map<R>(R Function(T value) f) => switch (this) {
        Ok(:final value) => Ok(f(value)),
        Err(:final error) => Err(error),
      };

  // Chains a step that can itself fail — otherwise you get Result<Result<..>>
  Result<R, E> flatMap<R>(Result<R, E> Function(T value) f) => switch (this) {
        Ok(:final value) => f(value),
        Err(:final error) => Err(error),
      };

  Result<T, F> mapError<F>(F Function(E error) f) => switch (this) {
        Ok(:final value) => Ok(value),
        Err(:final error) => Err(f(error)),
      };
}

final class Ok<T, E> extends Result<T, E> {
  const Ok(this.value);
  final T value;
}

final class Err<T, E> extends Result<T, E> {
  const Err(this.error);
  final E error;
}

