List<Message> mergeSorted(List<Message> cached, List<Message> fresh) {
  final out = <Message>[];
  final seen = <String>{};
  var i = 0, j = 0;

  void take(Message m) {
    if (seen.add(m.id)) out.add(m);      // add() is false when the id is already out
  }

  while (i < cached.length && j < fresh.length) {
    final c = cached[i], f = fresh[j];
    final byTime = c.sentAt.compareTo(f.sentAt);   // instants, not ==

    if (byTime == 0 && c.id == f.id) {   // same message in both: the server copy wins
      take(f);
      i++;
      j++;
      continue;
    }
    // deterministic tie-break so equal timestamps never reorder between runs
    if (byTime != 0 ? byTime < 0 : c.id.compareTo(f.id) < 0) {
      take(c);
      i++;
    } else {
      take(f);
      j++;
    }
  }
  while (i < cached.length) take(cached[i++]);
  while (j < fresh.length) take(fresh[j++]);
  return out;
}

void traps() {
  // ❌ Sorts again, and the dedupe inside is O(n^2) on top
  final naive = [...cached, ...fresh]..sort((a, b) => a.sentAt.compareTo(b.sentAt));
  final deduped = naive.fold<List<Message>>(
      [], (acc, m) => acc.any((x) => x.id == m.id) ? acc : (acc..add(m)));

  // ❌ == also compares the timezone flag
  final a = DateTime.utc(2026, 1, 1);
  final b = a.toLocal();
  print(a == b);                 // false
  print(a.isAtSameMomentAs(b));  // true  ✅
}

