class Comment {
  Comment(this.id, this.text, {this.children = const []});
  final String id;
  final String text;
  final List<Comment> children;
}

typedef Row = ({Comment comment, int depth});

List<Row> flatten(List<Comment> roots, {Set<String> collapsed = const {}}) {
  final out = <Row>[];
  // reversed on the way in => natural reading order on the way out
  final stack = <Row>[for (final c in roots.reversed) (comment: c, depth: 0)];

  while (stack.isNotEmpty) {
    final row = stack.removeLast();
    out.add(row);
    if (collapsed.contains(row.comment.id)) continue;   // subtree stays hidden
    for (final child in row.comment.children.reversed) {
      stack.add((comment: child, depth: row.depth + 1));
    }
  }
  return out;
}

// A flat API payload becomes a tree in one pass, then the same walk applies
List<Comment> buildTree(List<({String id, String? parentId, String text})> raw) {
  final byParent = groupBy(raw, (r) => r.parentId);
  List<Comment> childrenOf(String? id) => [
        for (final r in byParent[id] ?? const [])
          Comment(r.id, r.text, children: childrenOf(r.id)),
      ];
  return childrenOf(null);
}

// The list is virtualized again because it is a list
Widget build(BuildContext context) {
  final rows = _flattened;                     // computed in state, not here
  return ListView.builder(
    itemCount: rows.length,
    itemBuilder: (_, i) => Padding(
      padding: EdgeInsets.only(left: min(rows[i].depth, 6) * 12.0),
      child: Text(rows[i].comment.text),
    ),
  );
}

R Function(A) memo1<A, R>(R Function(A) f) {
  final cache = <A, R>{};
  return (a) => cache.putIfAbsent(a, () => f(a));   // one call per missing key
}

R Function(A, B) memo2<A, B, R>(R Function(A, B) f) {
  final cache = <(A, B), R>{};                      // record key: structural equality
  return (a, b) => cache.putIfAbsent((a, b), () => f(a, b));
}

