class LruCache<K, V> {
  LruCache(this.capacity) : assert(capacity > 0);

  final int capacity;
  final _entries = <K, V>{};        // LinkedHashMap: insertion order == recency order

  Iterable<K> get keys => _entries.keys;   // least recently used first
  int get length => _entries.length;

  V? get(K key) {
    final value = _entries.remove(key);    // unlink...
    if (value == null) return null;
    _entries[key] = value;                 // ...and re-insert at the most-recent end
    return value;
  }

  void put(K key, V value) {
    _entries.remove(key);                  // move an existing key to the end
    _entries[key] = value;
    if (_entries.length > capacity) {
      _entries.remove(_entries.keys.first);   // evict the least recently used
    }
  }

  void clear() => _entries.clear();

  // ❌ A FIFO wearing an LRU costume: recency is never updated on a read.
  V? getBroken(K key) => _entries[key];
}

void main() {
  final cache = LruCache<String, int>(2);
  cache
    ..put('a', 1)
    ..put('b', 2);

  cache.get('a');            // 'a' becomes the most recent
  cache.put('c', 3);         // evicts 'b', not 'a'
  print(cache.keys);         // (a, c)

  cache.put('c', 30);        // updating an existing key evicts nothing
  print(cache.length);       // 2

  // ❌ ConcurrentModificationError
  for (final k in cache.keys) {
    if (k == 'a') cache.put(k, 0);
  }
}

class RequestCoalescer {
  final _inFlight = <String, Future<dynamic>>{};

  Future<T> run<T>(String key, Future<T> Function() start) {
    final running = _inFlight[key];
    if (running != null) return running.then((value) => value as T);

    final future = start();
    _inFlight[key] = future;
    // whenComplete runs on success AND on error, so a failure is never cached
    return future.whenComplete(() => _inFlight.remove(key));
  }
}

