/// Runs [task] over [items] with at most [limit] in flight, results in order.
Future<List<R>> mapPooled<T, R>(
  List<T> items,
  int limit,
  Future<R> Function(T item) task,
) async {
  final results = List<R?>.filled(items.length, null);
  var next = 0; // one cursor shared by every worker

  Future<void> worker() async {
    while (true) {
      final i = next;
      if (i >= items.length) return;
      next = i + 1;                       // no await between read and bump: no race
      results[i] = await task(items[i]);  // the slot carries the order
    }
  }

  await Future.wait([
    for (var w = 0; w < limit && w < items.length; w++) worker(),
  ]);
  return [for (final r in results) r as R];
}

Future<void> demo(List<String> ids) async {
  // ❌ map() starts every request the moment it is iterated: 50 in flight
  await Future.wait(ids.map(api.fetch));

  // ❌ bounded, but one slow id idles three workers until the chunk ends
  final chunked = <Product>[];
  for (final chunk in ids.slices(4)) {
    chunked.addAll(await Future.wait(chunk.map(api.fetch)));
  }

  // ✅ the pool takes thunks, so nothing starts before its turn
  final products = await mapPooled(ids, 4, (id) => api.fetch(id));

  // ✅ same idea from package:pool — Future.wait preserves argument order
  final pool = Pool(4);
  final viaPool = await Future.wait([
    for (final id in ids) pool.withResource(() => api.fetch(id)),
  ]);
  await pool.close();
}

