class EventBus {
  final _ctrl = StreamController<Object>.broadcast();

  void emit(Object event) {
    if (!_ctrl.isClosed) _ctrl.add(event);
  }

  // where + cast is the idiom: Stream has no whereType outside rxdart.
  Stream<T> on<T extends Object>() => _ctrl.stream.where((e) => e is T).cast<T>();

  Future<void> dispose() => _ctrl.close();
}

