class CartChanged {
  const CartChanged(this.count);
  final int count;
}

final bus = EventBus();

// ── ❌ nobody owns the subscription ──
class _LeakyState extends State<CartBadge> {
  int _count = 0;

  @override
  void initState() {
    super.initState();
    bus.on<CartChanged>().listen((e) => setState(() => _count = e.count));
  }
  // no cancel in dispose -> the closure, this State and its Element stay reachable
  // from the singleton bus for the rest of the process
}

// ── ✅ the subscription has an owner ──
class _OwnedState extends State<CartBadge> {
  StreamSubscription<CartChanged>? _sub;
  int _count = 0;

  @override
  void initState() {
    super.initState();
    _sub = bus.on<CartChanged>().listen((e) => setState(() => _count = e.count));
  }

  @override
  void dispose() {
    _sub?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => Text('$_count');
}

// ── ✅✅ nothing to forget: StreamBuilder cancels in its own dispose ──
Widget badge() => StreamBuilder<CartChanged>(
      stream: bus.on<CartChanged>(),
      builder: (context, snap) => Text('${snap.data?.count ?? 0}'),
    );

import 'package:flutter/foundation.dart';

class Page<T> {
  Page(this.items, this.nextCursor);
  final List<T> items;
  final String? nextCursor; // null means: that was the last page
}

class PagingState<T> {
  PagingState({List<T>? items, this.hasMore = true, this.loading = false, this.error})
      : items = items ?? <T>[];

  final List<T> items;
  final bool hasMore;
  final bool loading;
  final Object? error;

  PagingState<T> copyWith({List<T>? items, bool? hasMore, bool? loading, Object? error}) =>
      PagingState<T>(
        items: items ?? this.items,
        hasMore: hasMore ?? this.hasMore,
        loading: loading ?? this.loading,
        error: error ?? this.error, // cannot clear a nullable field
      );
}

class PagingController<T> extends ChangeNotifier {
  PagingController(this._fetch);
  final Future<Page<T>> Function(String? cursor) _fetch;

  PagingState<T> state = PagingState<T>();
  String? _cursor;
  int _generation = 0;

  Future<void> loadMore() async {
    if (state.loading || !state.hasMore || state.error != null) return;
    final gen = _generation;
    _set(state.copyWith(loading: true));
    try {
      final page = await _fetch(_cursor);
      if (gen != _generation) return; // a refresh overtook us: drop the page
      _cursor = page.nextCursor;
      _set(state.copyWith(
        items: [...state.items, ...page.items],
        hasMore: page.nextCursor != null,
        loading: false,
      ));
    } catch (e) {
      if (gen != _generation) return;
      _set(state.copyWith(loading: false, error: e)); // _cursor untouched
    }
  }

  Future<void> retry() {
    _set(PagingState<T>(items: state.items, hasMore: state.hasMore)); // clears error
    return loadMore();
  }

  Future<void> refresh() {
    _generation++; // every response still in flight is now stale
    _cursor = null;
    _set(PagingState<T>());
    return loadMore();
  }

  void _set(PagingState<T> next) {
    state = next;
    notifyListeners();
  }
}

