import 'package:fake_async/fake_async.dart';
import 'package:test/test.dart';

class RateLimiter {
  RateLimiter({required this.max, required this.window});

  final int max;
  final Duration window;
  final Queue<DateTime> _grants = Queue<DateTime>();

  Future<T> run<T>(Future<T> Function() action) async {
    final at = _reserve(); // synchronous on purpose
    final wait = at.difference(clock.now());
    if (wait > Duration.zero) await Future<void>.delayed(wait);
    return action();
  }

  /// Books the next slot and returns the instant it may run.
  DateTime _reserve() {
    final now = clock.now();
    final cutoff = now.subtract(window);
    while (_grants.isNotEmpty && !_grants.first.isAfter(cutoff)) {
      _grants.removeFirst(); // outside the window: it no longer counts
    }
    // With max already booked, the next slot opens one window after the
    // max-th most recent grant.
    final at = _grants.length < max
        ? now
        : _grants.elementAt(_grants.length - max).add(window);
    _grants.addLast(at); // reserved before any await: two callers cannot both win
    return at;
  }
}

void main() {
  test('admits five per rolling minute', () {
    fakeAsync((async) {
      final limiter = RateLimiter(max: 5, window: const Duration(minutes: 1));
      final finished = <Duration>[];

      for (var i = 0; i < 6; i++) {
        limiter.run(() async => i).then((_) => finished.add(async.elapsed));
      }

      async.flushMicrotasks();
      expect(finished.length, 5); // the first five went straight through

      async.elapse(const Duration(minutes: 1));
      expect(finished.last, const Duration(minutes: 1)); // the sixth waited exactly
    });
  });
}

import 'dart:collection';

// ── Hand-rolled: the state machine written out ──
class Windows<E> extends IterableBase<List<E>> {
  Windows(this._source, this.size);
  final List<E> _source;
  final int size;

  @override
  Iterator<List<E>> get iterator => _WindowIterator(_source, size); // a NEW one each time
}

class _WindowIterator<E> implements Iterator<List<E>> {
  _WindowIterator(this._source, this._size);
  final List<E> _source;
  final int _size;
  int _start = -1;
  late List<E> _current;

  @override
  List<E> get current => _current; // only defined after moveNext() returned true

  @override
  bool moveNext() {
    _start++;
    if (_start + _size > _source.length) return false;
    _current = _source.sublist(_start, _start + _size);
    return true;
  }
}

// ── sync*: the same machine, generated by the compiler ──
Iterable<List<E>> windows<E>(List<E> source, int size) sync* {
  for (var i = 0; i + size <= source.length; i++) {
    yield source.sublist(i, i + size);
  }
}

// yield* delegates, so a lazy depth-first walk is two lines
Iterable<Node> preorder(Node node) sync* {
  yield node;
  for (final child in node.children) yield* preorder(child);
}

void main() {
  final w = windows([1, 2, 3, 4], 2);
  print(w.first);    // [1, 2] — only one window was ever built
  print(w.toList()); // runs the generator again, from the start
  print(w.length);   // and again: laziness means no memoisation
}

import 'dart:async';
import 'dart:math' as math;

class Fix {
  const Fix(this.lat, this.lon, this.at);
  final double lat;
  final double lon;
  final DateTime at; // the fix's own timestamp, not DateTime.now()
}

Stream<Fix> _gate(Stream<Fix> source, Duration minGap, double minMetres) async* {
  Fix? kept; // fresh per bind, so two subscriptions never share it
  await for (final fix in source) {
    if (kept == null ||
        (fix.at.difference(kept.at) >= minGap &&      // cheap gate first
            metresBetween(kept, fix) >= minMetres)) { // trig second
      kept = fix; // compare against what we emitted, never against the last input
      yield fix;
    }
  }
}

StreamTransformer<Fix, Fix> gpsGate({
  Duration minGap = const Duration(seconds: 5),
  double minMetres = 10,
}) =>
    StreamTransformer<Fix, Fix>.fromBind((s) => _gate(s, minGap, minMetres));

double metresBetween(Fix a, Fix b) {
  const r = 6371000.0; // mean Earth radius in metres
  final dLat = _rad(b.lat - a.lat);
  final dLon = _rad(b.lon - a.lon);
  final h = math.pow(math.sin(dLat / 2), 2) +
      math.cos(_rad(a.lat)) * math.cos(_rad(b.lat)) * math.pow(math.sin(dLon / 2), 2);
  return 2 * r * math.asin(math.sqrt(h));
}

double _rad(double deg) => deg * math.pi / 180;

// ── ❌ the state lives in the closure: shared by every bind of this instance ──
Fix? _lastKept;
final broken = StreamTransformer<Fix, Fix>.fromHandlers(
  handleData: (fix, sink) {
    if (_lastKept == null || metresBetween(_lastKept!, fix) >= 10) {
      _lastKept = fix;
      sink.add(fix);
    }
  },
);

void track(Stream<Fix> positions) {
  positions.transform(gpsGate()).listen(save);
}

