/// Returns null when the two structures match, else the first differing path.
String? firstDiff(Object? expected, Object? actual, [String path = r'$']) {
  if (expected is Map && actual is Map) {
    // Map iteration is insertion-ordered: sort so "first" is deterministic.
    final keys = <Object?>{...expected.keys, ...actual.keys}.toList()
      ..sort((a, b) => '$a'.compareTo('$b'));
    for (final k in keys) {
      if (!expected.containsKey(k)) return '$path.$k: unexpected (${actual[k]})';
      if (!actual.containsKey(k)) return '$path.$k: missing (expected ${expected[k]})';
      final d = firstDiff(expected[k], actual[k], '$path.$k');
      if (d != null) return d;
    }
    return null;
  }
  if (expected is List && actual is List) {
    if (expected.length != actual.length) {
      return '$path: length ${actual.length}, expected ${expected.length}';
    }
    for (var i = 0; i < expected.length; i++) {
      final d = firstDiff(expected[i], actual[i], '$path[$i]');
      if (d != null) return d;
    }
    return null;
  }
  // 1 and 1.0 are equal but have different runtimeTypes: let num compare by value.
  if (expected is! num && expected.runtimeType != actual.runtimeType) {
    return '$path: ${actual.runtimeType}, expected ${expected.runtimeType}';
  }
  if (expected is double && expected.isNaN) {
    return (actual is double && actual.isNaN) ? null : '$path: $actual, expected NaN';
  }
  return expected == actual ? null : '$path: $actual, expected $expected';
}

void main() {
  final expected = {'user': {'id': 7, 'tags': ['a', 'b']}, 'total': 12.5};
  final actual = {'user': {'id': 7, 'tags': ['a', 'c']}, 'total': 12.5};

  print(expected == actual); // false — identity, always
  print(const DeepCollectionEquality().equals(expected, actual)); // false, but where?

  // Fails with: Actual: '$.user.tags[1]: c, expected b'
  test('payload matches', () => expect(firstDiff(expected, actual), isNull));
}

import 'package:collection/collection.dart';

class TrieNode {
  final Map<int, TrieNode> children = {}; // keyed by code unit
  final List<int> ids = []; // product ids whose name ends here
}

class Trie {
  final _root = TrieNode();

  void insert(String name, int id) {
    var node = _root;
    for (final c in name.toLowerCase().codeUnits) {
      node = node.children.putIfAbsent(c, TrieNode.new);
    }
    node.ids.add(id);
  }

  List<int> startingWith(String prefix, {int limit = 10}) {
    var node = _root;
    for (final c in prefix.toLowerCase().codeUnits) {
      final next = node.children[c];
      if (next == null) return const []; // O(len(prefix)), nothing scanned
      node = next;
    }
    final out = <int>[];
    _collect(node, out, limit); // capped: "a" alone sits above ~40k words
    return out;
  }

  void _collect(TrieNode node, List<int> out, int limit) {
    for (final id in node.ids) {
      if (out.length >= limit) return;
      out.add(id);
    }
    for (final child in node.children.values) {
      if (out.length >= limit) return;
      _collect(child, out, limit);
    }
  }
}

// ── The version that usually ships: sorted list + two binary searches ──
class PrefixIndex {
  PrefixIndex(List<String> names)
      : _sorted = [for (final n in names) n.toLowerCase()]..sort();

  final List<String> _sorted;

  Iterable<String> startingWith(String prefix) {
    final q = prefix.toLowerCase();
    if (q.isEmpty) return _sorted;
    final lo = lowerBound(_sorted, q);
    final hi = lowerBound(_sorted, _bump(q));
    return _sorted.getRange(lo, hi); // one contiguous slice
  }

  // "abc" -> "abd": the exclusive upper bound of the prefix range
  String _bump(String s) =>
      s.substring(0, s.length - 1) +
      String.fromCharCode(s.codeUnitAt(s.length - 1) + 1);
}
